INSERT INTO raw_material_properties (raw_material_id, property_key, value_num, value_text, unit, source_version)
SELECT rm.id, p.property_key, CAST(p.value_num AS NUMERIC), CAST(p.value_text AS TEXT), CAST(p.unit AS TEXT), '2026-SandCasting'
FROM props p
JOIN raw_materials rm ON rm.grade = p.source_name AND rm.material_group = 'Sand Casting'
ON CONFLICT (raw_material_id, property_key) DO NOTHING;
